    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('a25c9e4a-805f-54b1-af81-7802334eeef5', v_aid, 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Дякую. Коли мені треба попередити про відсутність?", "Мені доведеться працювати позмінно?", "Де ви працювали раніше?"]'::jsonb, 0, null, '{}'::text[], 'Hvala. Kada moram najaviti odsutnost?', null, null, 'Прозвучало: «Hvala. Kada moram najaviti odsutnost?» — «Дякую. Коли мені треба попередити про відсутність?».', (select id from public.lessons where id = '99088d92-0f0c-52c2-b51f-548d903fc9ef'), 'PUBLISHED', 'claude_assessment_v5'),
  ('dcae22d4-02e6-5c60-8d8b-62085881df96', v_aid, 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Вона доглядальниця в будинку для літніх людей.", "У роздягальні, у кожного своя шафка.", "Хочеш кави? Кавовий автомат знову працює."]'::jsonb, 2, null, '{}'::text[], 'Hoćeš li kavu? Aparat za kavu opet radi.', null, null, 'Прозвучало: «Hoćeš li kavu? Aparat za kavu opet radi.» — «Хочеш кави? Кавовий автомат знову працює.».', (select id from public.lessons where id = 'ee016ba8-5160-581d-b440-1bcb7647173d'), 'PUBLISHED', 'claude_assessment_v5'),
  ('a8bb2a2a-a61f-5f30-a98b-124d5d0b91d1', v_aid, 3, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Бачимося в офісі по вівторках і четвергах.", "Запобіжник у порядку. Може, коротке замикання.", "Без проблем, вона поміститься в багажник."]'::jsonb, 0, null, '{}'::text[], 'Vidimo se u uredu utorkom i četvrtkom.', null, null, 'Прозвучало: «Vidimo se u uredu utorkom i četvrtkom.» — «Бачимося в офісі по вівторках і четвергах.».', (select id from public.lessons where id = 'd813e9c0-2331-59d8-90f1-cea7e9a61c7d'), 'PUBLISHED', 'claude_assessment_v5'),
  ('3b1be6cb-d59e-583a-a943-17687dd2e1e3', v_aid, 4, 'A1', 'reading', 'understand', 'multiple_choice', 'Коли починається ранкова зміна?', 'Raspored smjena', '["О 8", "О 6", "О 14"]'::jsonb, 1, null, '{}'::text[], null, 'RASPORED SMJENA – SKLADIŠTE
