  ('1b6c6efa-08b0-5512-a4d9-3866c1e2e754', v_aid, 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Можу, але дуже боляче.", "Картку медичного страхування й список ліків.", "Ні, я тут уперше."]'::jsonb, 2, null, '{}'::text[], 'Nisam, prvi put sam ovdje.', null, null, 'Прозвучало: «Nisam, prvi put sam ovdje.» — «Ні, я тут уперше.».', (select id from public.lessons where id = '08e31e8b-f8f7-5a80-89ed-093bc68dae03'), 'PUBLISHED', 'claude_assessment_v5'),
  ('5261719d-3f98-55ac-9192-1fc80997efed', v_aid, 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Що ти змінила?", "А порошок для дітей?", "У вас була температура?"]'::jsonb, 1, null, '{}'::text[], 'A prašak za djecu?', null, null, 'Прозвучало: «A prašak za djecu?» — «А порошок для дітей?».', (select id from public.lessons where id = '123e68fa-291f-5ad6-8403-51db7020d641'), 'PUBLISHED', 'claude_assessment_v5'),
  ('95ddb9c5-a644-50ae-8018-19f7e9e90fd9', v_aid, 3, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Дай мені пластир, швидко!", "У вас запалення горла. Це бактеріальна інфекція.", "Покажи. Рана сильно кровоточить."]'::jsonb, 2, null, '{}'::text[], 'Pokaži. Rana jako krvari.', null, null, 'Прозвучало: «Pokaži. Rana jako krvari.» — «Покажи. Рана сильно кровоточить.».', (select id from public.lessons where id = 'd5dee6c5-f510-57b9-a1ed-4b0a60e8e09a'), 'PUBLISHED', 'claude_assessment_v5'),
  ('d135ba1d-c5fe-51b3-ab7c-e98158f578a2', v_aid, 4, 'A1', 'reading', 'understand', 'multiple_choice', 'Кому пише Олена?', 'Dijete je bolesno', '["Виховательці", "Лікареві", "Чоловікові"]'::jsonb, 0, null, '{}'::text[], null, 'Olena: Dobro jutro, Sofija danas ne dolazi u vrtić. Ima temperaturu i kašlje.
Odgojiteljica: Dobro jutro! Žao mi je. Neka se odmara.
Olena: Hvala. Trebam li donijeti potvrdu od liječnika?
Odgojiteljica: Da, kad se vrati u vrtić, trebamo potvrdu od pedijatra.
Olena: U redu. Hvala i lijep dan!', 'Олена: Доброго ранку, Софія сьогодні не прийде в садок. У неї температура і кашель.
Вихователька: Доброго ранку! Мені шкода. Нехай відпочиває.
Олена: Дякую. Мені потрібно принести довідку від лікаря?
Вихователька: Так, коли вона повернеться в садок, нам потрібна довідка від педіатра.
Олена: Гаразд. Дякую і гарного дня!', 'Текст «Дитина хворіє». Правильна відповідь: «Виховательці».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('577eb2bd-ff6a-5168-be8d-75e689fbd651', v_aid, 5, 'A1', 'reading', 'understand', 'multiple_choice', 'Коли огляд?', 'Podsjetnik za pregled', '["Сьогодні о 10:30", "Завтра о 10:30", "Завтра о 13:00"]'::jsonb, 1, null, '{}'::text[], null, 'Poštovana, imate pregled kod dr. Jurić sutra u 10:30. Ponesite zdravstvenu iskaznicu i uputnicu. Ako ne možete doći, otkažite termin na broj 01 456 7890. Dođite deset minuta prije termina.', 'Шановна, у вас огляд у лікарки Юрич завтра о 10:30. Візьміть медичну картку страхування й направлення. Якщо не можете прийти, скасуйте прийом за номером 01 456 7890. Прийдіть за десять хвилин до прийому.', 'Текст «Нагадування про прийом». Правильна відповідь: «Завтра о 10:30».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('7c5186d6-618e-58c2-87b0-b5087a5c1f50', v_aid, 6, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Doktorice, kakva je dijagnoza?', '["Iznad stolića u dnevnom boravku.", "Imate upalu grla. To je bakterijska infekcija.", "Željeznica ima zamjenski autobus ispred kolodvora."]'::jsonb, 1, null, '{}'::text[], 'Doktorice, kakva je dijagnoza?', null, null, 'Діалог «Що зі мною?»: «Doktorice, kakva je dijagnoza?» (Пані лікарко, який діагноз?) — «Imate upalu grla. To je bakterijska infekcija.» (У вас запалення горла. Це бактеріальна інфекція.).', (select id from public.lessons where id = '431b51ad-baa3-5387-94ac-a7273fdb9263'), 'PUBLISHED', 'claude_assessment_v5'),
  ('cb7ef7a1-8ec1-51cc-846a-cc6f83163ffd', v_aid, 7, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Dobar dan, mogu li se naručiti kod doktorice Horvat?', '["Došla sam u Hrvatsku, pa sam dala otkaz.", "Odlične. Dodajem je u košaricu.", "Prvi slobodni termin je u četvrtak u deset."]'::jsonb, 2, null, '{}'::text[], 'Dobar dan, mogu li se naručiti kod doktorice Horvat?', null, null, 'Діалог «Дзвінок в амбулаторію»: «Dobar dan, mogu li se naručiti kod doktorice Horvat?» (Добрий день, можна записатися до лікарки Горват?) — «Prvi slobodni termin je u četvrtak u deset.» (Найближчий вільний час — у четвер о десятій.).', (select id from public.lessons where id = '08e31e8b-f8f7-5a80-89ed-093bc68dae03'), 'PUBLISHED', 'claude_assessment_v5'),
  ('23b844de-e380-5e22-96a4-127e59d0bba3', v_aid, 8, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Mama, kakva je ovo sirena?', '["Dvije najamnine. Ugovor je na godinu dana.", "To je samo proba uzbune, svake prve subote u mjesecu.", "Petnaest eura mjesečno, s dvadeset giga podataka."]'::jsonb, 1, null, '{}'::text[], 'Mama, kakva je ovo sirena?', null, null, 'Діалог «Сирена й землетрус»: «Mama, kakva je ovo sirena?» (Мамо, що це за сирена?) — «To je samo proba uzbune, svake prve subote u mjesecu.» (Це лише перевірка тривоги, щопершої суботи місяця.).', (select id from public.lessons where id = '692e9310-7a5b-5adf-9f0a-a66b72fc5459'), 'PUBLISHED', 'claude_assessment_v5'),
  ('aae2ef1f-90e3-5717-a5c8-7fe8f704ac2f', v_aid, 9, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Ima li nuspojava?', '["Rijetko. Pročitajte upute u kutiji.", "Oko tri i pol sata, sa stankom od petnaest minuta.", "Petnaest eura, s kacigom i lokotom."]'::jsonb, 0, null, '{}'::text[], 'Ima li nuspojava?', null, null, 'Діалог «Від горла й нежитю»: «Ima li nuspojava?» (Є побічні дії?) — «Rijetko. Pročitajte upute u kutiji.» (Рідко. Прочитайте інструкцію в коробці.).', (select id from public.lessons where id = '123e68fa-291f-5ad6-8403-51db7020d641'), 'PUBLISHED', 'claude_assessment_v5'),
  ('826d3d45-b956-5da9-a674-743b79ccbb9e', v_aid, 10, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Ima li temperaturu?', '["Термометр показав тридцять вісім з половиною.", "Пане лікарю, малий з ранку блює, і в нього пронос.", "Я його огляну, може, це запалення вуха."]'::jsonb, 0, null, '{}'::text[], null, 'Daša: Doktore, mali od jutros povraća i ima proljev.
Pedijatar: Ima li temperaturu?
Daša: Toplomjer je pokazao trideset osam i pol.
Pedijatar: Dajte mu čepić za temperaturu i neka pije puno vode.
Daša: Plače i drži se za uho.
Pedijatar: Pregledat ću ga, možda je upala uha.', 'Daša: Пане лікарю, малий з ранку блює, і в нього пронос.
Pedijatar: У нього температура?
Daša: Термометр показав тридцять вісім з половиною.
Pedijatar: Дайте йому свічку від температури, і хай п’є багато води.
Daša: Він плаче й тримається за вухо.
Pedijatar: Я його огляну, може, це запалення вуха.', 'Діалог «Дитина хворіє»: «Ima li temperaturu?» — «Toplomjer je pokazao trideset osam i pol.», тобто «Термометр показав тридцять вісім з половиною.».', (select id from public.lessons where id = '0df023bb-17fb-5006-91bf-3b911dd30295'), 'PUBLISHED', 'claude_assessment_v5'),
  ('a6fdd5f1-440a-55e4-9c6f-31268e968deb', v_aid, 11, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Što vam se dogodilo?', '["Ні, але мені довелося лягти.", "Так, уночі мене морозило, і я дуже пітніла.", "Учора я дуже погано почувалася. У мене було запаморочення."]'::jsonb, 2, null, '{}'::text[], null, 'Liječnica: Što vam se dogodilo?
Daša: Jučer sam se jako loše osjećala. Imala sam vrtoglavicu.
Liječnica: Jeste li pali u nesvijest?
Daša: Nisam, ali sam morala leći.
Liječnica: Jeste li imali temperaturu?
Daša: Jesam, noću sam imala zimicu i jako sam se znojila.', 'Liječnica: Що з вами сталося?
Daša: Учора я дуже погано почувалася. У мене було запаморочення.
Liječnica: Ви знепритомніли?
Daša: Ні, але мені довелося лягти.
Liječnica: У вас була температура?
Daša: Так, уночі мене морозило, і я дуже пітніла.', 'Діалог «Що сталося?»: «Što vam se dogodilo?» — «Jučer sam se jako loše osjećala. Imala sam vrtoglavicu.», тобто «Учора я дуже погано почувалася. У мене було запаморочення.».', (select id from public.lessons where id = '878c0712-e4e5-5a7d-aab5-510c781da0c7'), 'PUBLISHED', 'claude_assessment_v5'),
  ('992cad08-e455-5947-b463-5aac9220eb61', v_aid, 12, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Kako je tvoja mama?', '["Це хронічне, тож вона ходить на терапію двічі на тиждень.", "Не повністю, але відновлення добре, якщо регулярно займатися.", "Краще. У неї був грип, але вірус минув."]'::jsonb, 2, null, '{}'::text[], null, 'Marko: Kako je tvoja mama?
Darja: Bolje. Imala je gripu, ali virus je prošao.
Marko: A ono s leđima?
Darja: To je kronično, pa ide na terapiju dvaput tjedno.
Marko: Može li se to izliječiti?
Darja: Ne potpuno, ali oporavak je dobar ako redovito vježba.', 'Marko: Як твоя мама?
Darja: Краще. У неї був грип, але вірус минув.
Marko: А та проблема зі спиною?
Darja: Це хронічне, тож вона ходить на терапію двічі на тиждень.
Marko: Це можна вилікувати?
Darja: Не повністю, але відновлення добре, якщо регулярно займатися.', 'Діалог «Довге лікування»: «Kako je tvoja mama?» — «Bolje. Imala je gripu, ali virus je prošao.», тобто «Краще. У неї був грип, але вірус минув.».', (select id from public.lessons where id = '431b51ad-baa3-5387-94ac-a7273fdb9263'), 'PUBLISHED', 'claude_assessment_v5'),
  ('1066981b-3b7e-5617-8b83-236953ac4e35', v_aid, 13, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «У мене сильно болить зуб». Що ви скажете?', null, '["Upomoć! Požar!", "Imam jaku zubobolju.", "Došli smo na cijepljenje."]'::jsonb, 1, null, '{}'::text[], null, null, null, '«У мене сильно болить зуб.» — «Imam jaku zubobolju.».', (select id from public.lessons where id = '247c3445-6ba3-50f0-a441-9073d6734451'), 'PUBLISHED', 'claude_assessment_v5'),
  ('608a9814-496d-58b9-b805-86981db10c6f', v_aid, 14, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Це невідкладний випадок». Що ви скажете?', null, '["Što se dogodilo?", "Ovo je hitan slučaj.", "Živim zdravije."]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Це невідкладний випадок.» — «Ovo je hitan slučaj.».', (select id from public.lessons where id = '08e31e8b-f8f7-5a80-89ed-093bc68dae03'), 'PUBLISHED', 'claude_assessment_v5'),
  ('0c37aacf-bbba-5161-8eba-89d6d1beca75', v_aid, 15, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «холестерин»', null, '[]'::jsonb, null, 'kolesterol', '{}'::text[], null, null, null, '«холестерин» — kolesterol.', (select id from public.lessons where id = '293af384-4ee2-5746-80a8-e8ffdc7009bc'), 'PUBLISHED', 'claude_assessment_v5'),
  ('35f1c84b-baf7-578c-a38f-7256fe4cfca1', v_aid, 16, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «інфекція»', null, '[]'::jsonb, null, 'infekcija', '{}'::text[], null, null, null, '«інфекція» — infekcija.', (select id from public.lessons where id = '431b51ad-baa3-5387-94ac-a7273fdb9263'), 'PUBLISHED', 'claude_assessment_v5'),
  ('38a46dfd-4233-53ea-840c-198dc11ee56c', v_aid, 17, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «У будинку пожежа!»', null, '["je", "U", "požar!", "zgradi"]'::jsonb, null, 'U zgradi je požar!', array['Požar je u zgradi!']::text[], null, null, null, '«У будинку пожежа!» — «U zgradi je požar!».', (select id from public.lessons where id = '692e9310-7a5b-5adf-9f0a-a66b72fc5459'), 'PUBLISHED', 'claude_assessment_v5'),
  ('a6854640-200f-5dbb-9bf7-355ccb03cbf3', v_aid, 18, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Приймайте натщесерце.»', null, '["Uzimajte", "natašte.", "lijek"]'::jsonb, null, 'Uzimajte lijek natašte.', array['Lijek uzimajte natašte.']::text[], null, null, null, '«Приймайте натщесерце.» — «Uzimajte lijek natašte.».', (select id from public.lessons where id = '123e68fa-291f-5ad6-8403-51db7020d641'), 'PUBLISHED', 'claude_assessment_v5'),
  ('a068f45f-19c8-5acf-9bc9-61b986cae28d', v_aid, 19, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Рана кровоточить.»', null, '["krvari.", "Rana"]'::jsonb, null, 'Rana krvari.', '{}'::text[], null, null, null, '«Рана кровоточить.» — «Rana krvari.».', (select id from public.lessons where id = 'd5dee6c5-f510-57b9-a1ed-4b0a60e8e09a'), 'PUBLISHED', 'claude_assessment_v5'),
  ('1e59790a-c4e4-56ef-a80b-daa75c81b7de', v_aid, 20, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «У мене запалення горла.»', null, '[]'::jsonb, null, 'Imam upalu grla.', '{}'::text[], null, null, null, '«У мене запалення горла.» — «Imam upalu grla.».', (select id from public.lessons where id = '431b51ad-baa3-5387-94ac-a7273fdb9263'), 'PUBLISHED', 'claude_assessment_v5');
