-- Перевірка модуля A1.11 · 16 завдань
do $$
declare v_aid uuid; v_payload jsonb; v_shift int;
begin
  select id into v_aid from public.assessments where slug = 'a1-m11' and cefr = 'A1';
  if v_aid is null then raise exception 'Немає тесту a1-m11 — звірте базу'; end if;
  if exists (select 1 from public.assessment_items where id = '341c53a3-473a-5dd8-b7b8-609ae9e5d82a') then return; end if;  -- уже оновлено
  if (select module_id from public.assessments where id = v_aid) is distinct from '7ed566a6-0272-5422-96e4-1ee69a1c41f1'::uuid then
    raise exception 'Тест a1-m11 прив’язаний не до модуля A1.11 — звірте базу';
  end if;
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'a1_dupes: перевірку оновлено після плану «Дублі й сенс уроків» (PR 3) — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Після модуля: 16 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~8 хв.', estimated_minutes = 8 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('341c53a3-473a-5dd8-b7b8-609ae9e5d82a', v_aid, 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Мамо, прочитай мені казку на ніч!", "Звісно, це найкращий гарнір!", "Про дракона! І щоб був щасливий кінець."]'::jsonb, 2, null, '{}'::text[], 'O zmaju! I neka ima sretan kraj.', null, null, 'Прозвучало: «O zmaju! I neka ima sretan kraj.» — «Про дракона! І щоб був щасливий кінець.».', (select id from public.lessons where id = '8bb4331d-c7c0-5039-acf9-756684424039'), 'PUBLISHED', 'claude_assessment_v5'),
  ('b618b314-c4d2-5c7a-82ca-574687a772d7', v_aid, 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Хто такі дзвонарі?", "Ти бачила статую Григорія Нинського?", "Де ви зустрічатимете Новий рік?"]'::jsonb, 0, null, '{}'::text[], 'Tko su zvončari?', null, null, 'Прозвучало: «Tko su zvončari?» — «Хто такі дзвонарі?».', (select id from public.lessons where id = 'b026f1b1-879d-59b5-8506-ee99e128c9c1'), 'PUBLISHED', 'claude_assessment_v5'),
  ('bc88433b-3940-577d-aa5f-55bd21b2f9dd', v_aid, 3, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["А Тіла Христового? Воно завжди в четвер.", "Для мене самоборська кремшніта, але скуштуй і фрітуле.", "Добрий день, контроль квитків. Ваш квиток, будь ласка."]'::jsonb, 1, null, '{}'::text[], 'Za mene samoborska kremšnita, ali probaj i fritule.', null, null, 'Прозвучало: «Za mene samoborska kremšnita, ali probaj i fritule.» — «Для мене самоборська кремшніта, але скуштуй і фрітуле.».', (select id from public.lessons where id = 'f1b2093d-9699-59af-92b9-ed7bdf7fad49'), 'PUBLISHED', 'claude_assessment_v5'),
  ('036282ae-08cf-5d80-ada5-94ba8541c4be', v_aid, 4, 'A1', 'reading', 'understand', 'multiple_choice', 'Що роблять гості в багатьох домах?', 'Hrvatski običaji: kava i gosti', '["Знімають взуття", "Приносять вино", "Готують обід"]'::jsonb, 0, null, '{}'::text[], null, 'U Hrvatskoj ljudi često idu na kavu. Kava nije samo kava – to je vrijeme za prijatelje. Kad idete u goste, donesite nešto malo, na primjer kolač. U puno kuća gosti se izuju. Domaćica uvijek nudi jelo i piće, jer su Hrvati vrlo gostoljubivi.', 'У Хорватії люди часто ходять на каву. Кава — це не просто кава, це час для друзів. Коли йдете в гості, принесіть щось невелике, наприклад тістечко. У багатьох домах гості знімають взуття. Господиня завжди пропонує їжу й напої, бо хорвати дуже гостинні.', 'Текст «Хорватські звичаї: кава й гості». Правильна відповідь: «Знімають взуття».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('0daf834a-ee49-53c6-bc1c-b83d284398f4', v_aid, 5, 'A1', 'reading', 'understand', 'multiple_choice', 'Що варто принести в гості?', 'Hrvatski običaji: kava i gosti', '["Щось невелике, наприклад тістечко", "Нічого", "Дорогий подарунок"]'::jsonb, 0, null, '{}'::text[], null, 'U Hrvatskoj ljudi često idu na kavu. Kava nije samo kava – to je vrijeme za prijatelje. Kad idete u goste, donesite nešto malo, na primjer kolač. U puno kuća gosti se izuju. Domaćica uvijek nudi jelo i piće, jer su Hrvati vrlo gostoljubivi.', 'У Хорватії люди часто ходять на каву. Кава — це не просто кава, це час для друзів. Коли йдете в гості, принесіть щось невелике, наприклад тістечко. У багатьох домах гості знімають взуття. Господиня завжди пропонує їжу й напої, бо хорвати дуже гостинні.', 'Текст «Хорватські звичаї: кава й гості». Правильна відповідь: «Щось невелике, наприклад тістечко».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('116b67d8-7bc0-5f6d-ab61-a5f1ab18c6cc', v_aid, 6, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Hoćemo li bojiti jaja?', '["Petnaest eura mjesečno, s dvadeset giga podataka.", "Hoćemo! Djeca će napraviti pisanice.", "Jučer sam se jako loše osjećala. Imala sam vrtoglavicu."]'::jsonb, 1, null, '{}'::text[], 'Hoćemo li bojiti jaja?', null, null, 'Діалог «Великдень»: «Hoćemo li bojiti jaja?» (Будемо фарбувати яйця?) — «Hoćemo! Djeca će napraviti pisanice.» (Будемо! Діти зроблять писанки.).', (select id from public.lessons where id = 'f67bd38c-a41c-51df-b9c0-081737600fce'), 'PUBLISHED', 'claude_assessment_v5'),
  ('2656eada-f4e0-5bdc-b2c0-671f19322df4', v_aid, 7, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Zašto toliko zvone?', '["To je stari običaj. Tjeraju zimu i zle duhove.", "Prvo na određeno, s probnim radom od tri mjeseca.", "Za to postoji cjepivo, pitajte doktoricu."]'::jsonb, 0, null, '{}'::text[], 'Zašto toliko zvone?', null, null, 'Діалог «Дзвонарі»: «Zašto toliko zvone?» (Чому вони так дзвонять?) — «To je stari običaj. Tjeraju zimu i zle duhove.» (Це давній звичай. Вони проганяють зиму й злих духів.).', (select id from public.lessons where id = 'b026f1b1-879d-59b5-8506-ee99e128c9c1'), 'PUBLISHED', 'claude_assessment_v5'),
  ('d3089f35-b59c-5af5-bcb5-96a8db495c4c', v_aid, 8, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Peka zvuči odlično. Koliko se čeka?', '["Oko sat vremena. Za početak preporučujem pršut i paški sir.", "Balet. Ulaznice su još u prodaji.", "Riba na žaru. Potvrdit ću vam rezervaciju porukom."]'::jsonb, 0, null, '{}'::text[], 'Peka zvuči odlično. Koliko se čeka?', null, null, 'Діалог «У конобі»: «Peka zvuči odlično. Koliko se čeka?» (Пека звучить чудово. Скільки чекати?) — «Oko sat vremena. Za početak preporučujem pršut i paški sir.» (Близько години. Для початку раджу пршут і паґський сир.).', (select id from public.lessons where id = 'f1b2093d-9699-59af-92b9-ed7bdf7fad49'), 'PUBLISHED', 'claude_assessment_v5'),
  ('b04357cf-6598-50f3-88bf-fcc0d807d0b2', v_aid, 9, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Kada su izgradili ove zidine?', '["Це Ловрієнац. Колись там жили вояки.", "Їх будували століттями, ще в середньовіччі.", "Ласкаво просимо! Я ваш туристичний гід."]'::jsonb, 1, null, '{}'::text[], null, 'Ivan: Dobro došli! Ja sam vaš turistički vodič.
Daša: Kada su izgradili ove zidine?
Ivan: Gradili su ih stoljećima, još u srednjem vijeku.
Daša: A što je ona velika tvrđava?
Ivan: To je Lovrijenac. Nekada su ondje živjeli vojnici.
Daša: Možemo li se popeti gore?', 'Ivan: Ласкаво просимо! Я ваш туристичний гід.
Daša: Коли збудували ці мури?
Ivan: Їх будували століттями, ще в середньовіччі.
Daša: А що це за велика фортеця?
Ivan: Це Ловрієнац. Колись там жили вояки.
Daša: Можна піднятися нагору?', 'Діалог «Екскурсія Дубровником»: «Kada su izgradili ove zidine?» — «Gradili su ih stoljećima, još u srednjem vijeku.», тобто «Їх будували століттями, ще в середньовіччі.».', (select id from public.lessons where id = 'd9ef1de4-f4db-590e-bafd-474f84c8e03f'), 'PUBLISHED', 'claude_assessment_v5'),
  ('43ca5bb7-a0be-55fe-b8ae-c12908cbc64e', v_aid, 10, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Marko, radiš li tridesetog svibnja?', '["П’ятого серпня — День перемоги, а п’ятнадцятого — Успіння Богородиці.", "Ні, це День державності, неробочий день.", "Добрий вечір! Сьогодні фірмова страва — пека з восьминога."]'::jsonb, 1, null, '{}'::text[], null, 'Daša: Marko, radiš li tridesetog svibnja?
Marko: Ne, to je Dan državnosti, neradni dan.
Daša: A Tijelovo? Ono je uvijek u četvrtak.
Marko: Onda uzmem petak i imam produženi vikend!
Daša: A u kolovozu?
Marko: Petog kolovoza je Dan pobjede, a petnaestog Velika Gospa.', 'Daša: Марко, ти працюєш тридцятого травня?
Marko: Ні, це День державності, неробочий день.
Daša: А Тіла Христового? Воно завжди в четвер.
Marko: Тоді візьму п’ятницю, і в мене довгі вихідні!
Daša: А в серпні?
Marko: П’ятого серпня — День перемоги, а п’ятнадцятого — Успіння Богородиці.', 'Діалог «Календар свят»: «Marko, radiš li tridesetog svibnja?» — «Ne, to je Dan državnosti, neradni dan.», тобто «Ні, це День державності, неробочий день.».', (select id from public.lessons where id = '33c041a0-e71a-55c1-94c8-64941876c6d2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('8cb5e487-4e86-5884-9153-737510aaa16a', v_aid, 11, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Яка мораль цієї казки?». Що ви скажете?', null, '["Koja je pouka ove priče?", "Koji je vaš specijalitet?", "Živjeli!"]'::jsonb, 0, null, '{}'::text[], null, null, null, '«Яка мораль цієї казки?» — «Koja je pouka ove priče?».', (select id from public.lessons where id = '8bb4331d-c7c0-5039-acf9-756684424039'), 'PUBLISHED', 'claude_assessment_v5'),
  ('300a5e77-e65c-54e1-b6df-df39b0ed804f', v_aid, 12, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я йду на карнавал з колегами». Що ви скажете?', null, '["Idem na karneval s kolegama.", "Sretan imendan!", "Ovo je najbolje jelo."]'::jsonb, 0, null, '{}'::text[], null, null, null, '«Я йду на карнавал з колегами.» — «Idem na karneval s kolegama.».', (select id from public.lessons where id = 'b026f1b1-879d-59b5-8506-ee99e128c9c1'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ed9f5e1e-1e70-54f3-9466-6215774feb06', v_aid, 13, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «традиція»', null, '[]'::jsonb, null, 'tradicija', '{}'::text[], null, null, null, '«традиція» — tradicija.', (select id from public.lessons where id = 'f67bd38c-a41c-51df-b9c0-081737600fce'), 'PUBLISHED', 'claude_assessment_v5'),
  ('f01c0053-cc00-58d1-a903-b0e6d4eaaeac', v_aid, 14, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Ми гуляли вузькими вуличками.»', null, '["Šetali", "smo", "uličicama.", "uskim"]'::jsonb, null, 'Šetali smo uskim uličicama.', '{}'::text[], null, null, null, '«Ми гуляли вузькими вуличками.» — «Šetali smo uskim uličicama.».', (select id from public.lessons where id = 'd9ef1de4-f4db-590e-bafd-474f84c8e03f'), 'PUBLISHED', 'claude_assessment_v5'),
  ('998fc9a5-b20b-5291-aa3b-68c0665b44f1', v_aid, 15, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Пршут смачніший за шинку.»', null, '["šunke.", "je", "ukusniji", "od", "Pršut"]'::jsonb, null, 'Pršut je ukusniji od šunke.', '{}'::text[], null, null, null, '«Пршут смачніший за шинку.» — «Pršut je ukusniji od šunke.».', (select id from public.lessons where id = 'f1b2093d-9699-59af-92b9-ed7bdf7fad49'), 'PUBLISHED', 'claude_assessment_v5'),
  ('99c1a9a7-f0d7-50c1-ac9d-480e3a3d7fdb', v_aid, 16, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Я не вмію зав’язувати краватку.»', null, '[]'::jsonb, null, 'Ne znam vezati kravatu.', '{}'::text[], null, null, null, '«Я не вмію зав’язувати краватку.» — «Ne znam vezati kravatu.».', (select id from public.lessons where id = '5ae02c5f-7ba1-5b59-be71-f744d6e9b169'), 'PUBLISHED', 'claude_assessment_v5');
  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  values ('assessment', v_aid, 'PUBLISHED', 'PUBLISHED', 'auto_passed', 'script', '[]'::jsonb, 'Бета: перевірки рівня A1 за схемою 2026-11-07 після плану «Дублі й сенс уроків» (PR 3, рішення власника 2026-11-17): тест модуля A1.11 наново (8 уроків з трьома новими). Завдання — з діалогів, вправ і текстів уроків. Потрібна перевірка носієм.');
end $$;

-- Перевірка модуля A1.12 · 14 завдань
do $$
declare v_aid uuid; v_payload jsonb; v_shift int;
begin
  select id into v_aid from public.assessments where slug = 'a1-m12' and cefr = 'A1';
  if v_aid is null then raise exception 'Немає тесту a1-m12 — звірте базу'; end if;
  if exists (select 1 from public.assessment_items where id = 'bcece8ea-3d55-5e6a-ab4c-a1789c0c51d0') then return; end if;  -- уже оновлено
  if (select module_id from public.assessments where id = v_aid) is distinct from '5a6eadc1-9da1-52c0-a50d-943a3fbffe70'::uuid then
    raise exception 'Тест a1-m12 прив’язаний не до модуля A1.12 — звірте базу';
  end if;
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'a1_dupes: перевірку оновлено після плану «Дублі й сенс уроків» (PR 3) — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Після модуля: 14 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~7 хв.', estimated_minutes = 7 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('bcece8ea-3d55-5e6a-ab4c-a1789c0c51d0', v_aid, 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Але мені потрібен новий пенал, старий порвався!", "Три ручки: синя, червона й чорна.", "Прошу. Бачу, у вас регулярні надходження."]'::jsonb, 0, null, '{}'::text[], 'Ali trebam novu pernicu, stara je potrgana!', null, null, 'Прозвучало: «Ali trebam novu pernicu, stara je potrgana!» — «Але мені потрібен новий пенал, старий порвався!».', (select id from public.lessons where id = 'e4904007-82bc-5759-89a9-05fb7a2c65c5'), 'PUBLISHED', 'claude_assessment_v5'),
  ('73eaf084-2237-52d6-b5e3-51855ccb3c6d', v_aid, 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Усередині на касі, карткою чи готівкою.", "Мені потрібна виписка з рахунку за останні три місяці.", "Так, і тапочки. Діти часто забруднюються."]'::jsonb, 2, null, '{}'::text[], 'Morate, i papuče. Djeca se često zaprljaju.', null, null, 'Прозвучало: «Morate, i papuče. Djeca se često zaprljaju.» — «Так, і тапочки. Діти часто забруднюються.».', (select id from public.lessons where id = '42c31cfb-8680-5450-8453-245f3abd475a'), 'PUBLISHED', 'claude_assessment_v5'),
  ('cd445a1c-225f-5462-9bb6-f70a83d8dd4d', v_aid, 3, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Добрий день, я хочу відкрити поточний рахунок.", "Встав картку й введи PIN.", "Свідоцтво про народження, медичну довідку й ваш OIB."]'::jsonb, 1, null, '{}'::text[], 'Ubaci karticu i unesi PIN.', null, null, 'Прозвучало: «Ubaci karticu i unesi PIN.» — «Встав картку й введи PIN.».', (select id from public.lessons where id = '1c468857-b9aa-5143-aa84-6ea02aa2443c'), 'PUBLISHED', 'claude_assessment_v5'),
  ('9b4efd6d-7e30-5996-951d-0ed4d4988b60', v_aid, 4, 'A1', 'reading', 'understand', 'multiple_choice', 'Що банк відкрив пані Коваленко?', 'E-mail iz banke', '["Кредит", "Депозит", "Поточний рахунок"]'::jsonb, 2, null, '{}'::text[], null, 'Poštovana gospođo Kovalenko,
Vaš tekući račun je otvoren. Debitnu karticu možete pokupiti u banci od ponedjeljka. Za internetsko bankarstvo trebate mobilni token. Provizija za račun je 2 eura mjesečno.
Lijep pozdrav,
Vaša banka', 'Шановна пані Коваленко,
ваш поточний рахунок відкрито. Дебетову картку можна забрати в банку з понеділка. Для інтернет-банкінгу вам потрібен мобільний токен. Комісія за рахунок — 2 євро на місяць.
З повагою,
ваш банк', 'Текст «Лист із банку». Правильна відповідь: «Поточний рахунок».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('98f4cda9-ac42-58a1-8bba-c155c7c39985', v_aid, 5, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Obična ili brza pošta?', '["U kutiji, na dnu. I vijci su u maloj vrećici.", "Prvo oguli jabuke i nasjeckaj ih.", "Obična. Imam i obavijest, trebam preuzeti pošiljku."]'::jsonb, 2, null, '{}'::text[], 'Obična ili brza pošta?', null, null, 'Діалог «На пошті»: «Obična ili brza pošta?» (Звичайна чи експрес-пошта?) — «Obična. Imam i obavijest, trebam preuzeti pošiljku.» (Звичайна. У мене ще повідомлення, мені треба забрати відправлення.).', (select id from public.lessons where id = '1c468857-b9aa-5143-aa84-6ea02aa2443c'), 'PUBLISHED', 'claude_assessment_v5'),
  ('78e47a2d-d777-58d2-97ea-49260aaa83ca', v_aid, 6, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Ima li moja kći hrvatski jezik svaki dan?', '["Jučer sam se jako loše osjećala. Imala sam vrtoglavicu.", "Ima, a tjelesni odgoj dvaput tjedno.", "U sali za sastanke na drugom katu."]'::jsonb, 1, null, '{}'::text[], 'Ima li moja kći hrvatski jezik svaki dan?', null, null, 'Діалог «Батьківські збори»: «Ima li moja kći hrvatski jezik svaki dan?» (Чи в моєї доньки хорватська мова щодня?) — «Ima, a tjelesni odgoj dvaput tjedno.» (Так, а фізкультуру двічі на тиждень.).', (select id from public.lessons where id = '7c8e16ec-03f3-55dd-a61a-fb59c2401692'), 'PUBLISHED', 'claude_assessment_v5'),
  ('fe0bf17e-70fd-5b65-9848-e9b863d04c60', v_aid, 7, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Kolika je mjesečna naknada?', '["Tri eura. Uz račun dobivate debitnu karticu i mobilno bankarstvo.", "Organizacija. Volim odgovornost.", "Natašte, ujutro. Progutajte ih s puno vode."]'::jsonb, 0, null, '{}'::text[], 'Kolika je mjesečna naknada?', null, null, 'Діалог «Відкриваю рахунок»: «Kolika je mjesečna naknada?» (Яка щомісячна плата?) — «Tri eura. Uz račun dobivate debitnu karticu i mobilno bankarstvo.» (Три євро. До рахунку ви отримуєте дебетову картку й мобільний банкінг.).', (select id from public.lessons where id = 'fee5b77b-dc3b-5fd5-818a-c5496e95c23b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('08fc70fe-a4b2-5e69-b7c7-c343582bc50c', v_aid, 8, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Što trebam donijeti?', '["Паспорт, підтвердження житла й підтвердження коштів на утримання.", "Сплатіть його до подання. Рішення отримаєте поштою.", "Добрий день, у мене наступного місяця спливає тимчасове проживання."]'::jsonb, 0, null, '{}'::text[], null, 'Daša: Dobar dan, moj privremeni boravak istječe sljedeći mjesec.
Službenica: Zahtjev za produljenje predajte najkasnije šezdeset dana prije isteka.
Daša: Što trebam donijeti?
Službenica: Putovnicu, dokaz o smještaju i dokaz o sredstvima za uzdržavanje.
Daša: A upravna pristojba?
Službenica: Platite je prije predaje. Rješenje dobivate poštom.', 'Daša: Добрий день, у мене наступного місяця спливає тимчасове проживання.
Službenica: Заяву на продовження подайте не пізніше ніж за шістдесят днів до закінчення терміну.
Daša: Що мені треба принести?
Službenica: Паспорт, підтвердження житла й підтвердження коштів на утримання.
Daša: А адміністративний збір?
Službenica: Сплатіть його до подання. Рішення отримаєте поштою.', 'Діалог «У відділі для іноземців»: «Što trebam donijeti?» — «Putovnicu, dokaz o smještaju i dokaz o sredstvima za uzdržavanje.», тобто «Паспорт, підтвердження житла й підтвердження коштів на утримання.».', (select id from public.lessons where id = 'fe2839bc-fd72-5e8b-bc0e-937d48a90aa8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ad5b6ecf-919d-5664-b268-5081d0695ea3', v_aid, 9, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Ne, hvala. Mogu li dobiti dopušteno prekoračenje?', '["Можна, до суми однієї зарплати.", "Добрий день, мене цікавить інтенсивний курс хорватської.", "Добрий день, надсилаю цей лист рекомендованим, з повідомленням про вручення."]'::jsonb, 0, null, '{}'::text[], null, 'Darja: Trebam izvod s računa za zadnja tri mjeseca.
Službenik: Izvolite. Vidim da imate redovite uplate.
Darja: Da. Zanima me i štedni račun. Kolika je kamata?
Službenik: Dva posto godišnje. Želite li i kreditnu karticu?
Darja: Ne, hvala. Mogu li dobiti dopušteno prekoračenje?
Službenik: Možete, do iznosa jedne plaće.', 'Darja: Мені потрібна виписка з рахунку за останні три місяці.
Službenik: Прошу. Бачу, у вас регулярні надходження.
Darja: Так. Мене цікавить і ощадний рахунок. Який відсоток?
Službenik: Два відсотки на рік. Бажаєте також кредитну картку?
Darja: Ні, дякую. А можна дозволений овердрафт?
Službenik: Можна, до суми однієї зарплати.', 'Діалог «Виписка й заощадження»: «Ne, hvala. Mogu li dobiti dopušteno prekoračenje?» — «Možete, do iznosa jedne plaće.», тобто «Можна, до суми однієї зарплати.».', (select id from public.lessons where id = 'fee5b77b-dc3b-5fd5-818a-c5496e95c23b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('2f7d99df-401c-5b1e-b0e4-f201aa5bd42b', v_aid, 10, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Де розклад уроків?». Що ви скажете?', null, '["Gdje je raspored sati?", "Koja je vaša razina?", "U kojem si razredu?"]'::jsonb, 0, null, '{}'::text[], null, null, null, '«Де розклад уроків?» — «Gdje je raspored sati?».', (select id from public.lessons where id = '7c8e16ec-03f3-55dd-a61a-fb59c2401692'), 'PUBLISHED', 'claude_assessment_v5'),
  ('08722392-61c3-5195-a5cb-d599c8eaedfd', v_aid, 11, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Де нотаріус?». Що ви скажете?', null, '["Gdje je javni bilježnik?", "Trebam debitnu karticu.", "Ima li slobodnih mjesta?"]'::jsonb, 0, null, '{}'::text[], null, null, null, '«Де нотаріус?» — «Gdje je javni bilježnik?».', (select id from public.lessons where id = 'fe2839bc-fd72-5e8b-bc0e-937d48a90aa8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('f7a69665-48fb-5186-99fc-087cabe23037', v_aid, 12, 'A1', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «словник»', null, '[]'::jsonb, null, 'rječnik', '{}'::text[], null, null, null, '«словник» — rječnik.', (select id from public.lessons where id = '11b565a4-1e2a-50d2-8d9d-c05e84371402'), 'PUBLISHED', 'claude_assessment_v5'),
  ('b66b909f-1a7a-537b-88f0-fcee2fd93a9d', v_aid, 13, 'A1', 'writing', 'produce', 'sentence_builder', 'Складіть: «Де мій пенал?»', null, '["pernica?", "moja", "Gdje", "je"]'::jsonb, null, 'Gdje je moja pernica?', '{}'::text[], null, null, null, '«Де мій пенал?» — «Gdje je moja pernica?».', (select id from public.lessons where id = 'e4904007-82bc-5759-89a9-05fb7a2c65c5'), 'PUBLISHED', 'claude_assessment_v5'),
  ('7ef8e326-1b79-5554-b1d2-c849c67d3dcb', v_aid, 14, 'A1', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Рекомендованим, будь ласка.»', null, '[]'::jsonb, null, 'Preporučeno, molim.', '{}'::text[], null, null, null, '«Рекомендованим, будь ласка.» — «Preporučeno, molim.».', (select id from public.lessons where id = '1c468857-b9aa-5143-aa84-6ea02aa2443c'), 'PUBLISHED', 'claude_assessment_v5');
