-- Фінальна перевірка рівня A1 · 48 завдань
do $$
declare v_aid uuid; v_payload jsonb; v_shift int;
begin
  select id into v_aid from public.assessments where slug = 'a1-final' and cefr = 'A1';
  if v_aid is null then raise exception 'Немає тесту a1-final — звірте базу'; end if;
  if exists (select 1 from public.assessment_items where id = '1bbf4e25-3eea-5a11-ae19-72aaf74b46c4') then return; end if;  -- уже оновлено
  select jsonb_build_object('assessment', to_jsonb(a),
         'items', (select coalesce(jsonb_agg(to_jsonb(i) order by i.order_index), '[]'::jsonb)
                     from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED'))
    into v_payload from public.assessments a where a.id = v_aid;
  insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
  values ('assessment', v_aid, coalesce((select max(version) from public.content_versions where entity_type = 'assessment' and entity_id = v_aid), 0) + 1,
          v_payload, 'a1_dupes: перевірку оновлено після плану «Дублі й сенс уроків» (PR 3) — старі завдання');
  select (coalesce(max(order_index), 0) / 100 + 1) * 100 into v_shift from public.assessment_items where assessment_id = v_aid;
  update public.assessment_items set status = 'DEPRECATED', order_index = order_index + v_shift
   where assessment_id = v_aid and status = 'PUBLISHED';
  update public.assessments set description_ua = 'Кінець рівня (усі 13 модулів A1): 48 завдань на 4 навички. ~25 хв.', estimated_minutes = 25 where id = v_aid;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, answer_alternatives, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('1bbf4e25-3eea-5a11-ae19-72aaf74b46c4', v_aid, 1, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Даріє, по радіо кажуть, що наближається спека.", "Ми їдемо машиною, тож беремо пором.", "Я складу план подорожі сьогодні ввечері."]'::jsonb, 2, null, '{}'::text[], 'Napravit ću plan puta večeras.', null, null, 'Прозвучало: «Napravit ću plan puta večeras.» — «Я складу план подорожі сьогодні ввечері.».', (select id from public.lessons where id = '373074e1-3c4b-5d0f-a4f3-3ed06e0904f2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('73bb7959-964f-59cd-b608-2abfa47122f9', v_aid, 2, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Мамо, прочитай мені казку на ніч!", "Ні, було забагато людей. Піду завтра зранку.", "А я буду кішкою, з вушками й хвостом."]'::jsonb, 2, null, '{}'::text[], 'A ja ću biti mačka, s ušima i repom.', null, null, 'Прозвучало: «A ja ću biti mačka, s ušima i repom.» — «А я буду кішкою, з вушками й хвостом.».', (select id from public.lessons where id = 'b026f1b1-879d-59b5-8506-ee99e128c9c1'), 'PUBLISHED', 'claude_assessment_v5'),
  ('41f72eda-277f-5f4b-aafd-1807ef68a7c0', v_aid, 3, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Як приймати ці капсули?", "Що ти змінила?", "А що робимо, коли землетрус?"]'::jsonb, 0, null, '{}'::text[], 'Kako uzimati ove kapsule?', null, null, 'Прозвучало: «Kako uzimati ove kapsule?» — «Як приймати ці капсули?».', (select id from public.lessons where id = '123e68fa-291f-5ad6-8403-51db7020d641'), 'PUBLISHED', 'claude_assessment_v5'),
  ('36216c1e-fdb5-5d32-8ac9-132f214fabc9', v_aid, 4, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Це від вологи. Треба щодня провітрювати.", "Це дуже мило з вашого боку.", "Приклей її клеєм для плитки."]'::jsonb, 0, null, '{}'::text[], 'To je od vlage. Trebaš prozračiti svaki dan.', null, null, 'Прозвучало: «To je od vlage. Trebaš prozračiti svaki dan.» — «Це від вологи. Треба щодня провітрювати.».', (select id from public.lessons where id = '62b118f9-a5e0-587b-82f8-39de181ddeba'), 'PUBLISHED', 'claude_assessment_v5'),
  ('67c99e3b-7c99-5ed7-a4fb-8464d608e397', v_aid, 5, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Добре, головне одужуй. Роботу надолужиш потім.", "Ні, але вимагає пунктуальності.", "А я шукаю роботу доставником або охоронцем."]'::jsonb, 2, null, '{}'::text[], 'Ja tražim posao kao dostavljač ili čuvar.', null, null, 'Прозвучало: «Ja tražim posao kao dostavljač ili čuvar.» — «А я шукаю роботу доставником або охоронцем.».', (select id from public.lessons where id = 'b369f01f-4a84-57b4-98cb-150d236f4d7f'), 'PUBLISHED', 'claude_assessment_v5'),
  ('bc67fc96-f059-57c0-9bec-44e9ebf1d321', v_aid, 6, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["У мене сто непрочитаних повідомлень!", "Ви тричі ввели неправильний пароль.", "Треба заповнити бланк і завантажити направлення."]'::jsonb, 2, null, '{}'::text[], 'Treba ispuniti obrazac i učitati uputnicu.', null, null, 'Прозвучало: «Treba ispuniti obrazac i učitati uputnicu.» — «Треба заповнити бланк і завантажити направлення.».', (select id from public.lessons where id = '953e12fb-a6f6-5ae5-aa7a-ebfe248d24da'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ad918a62-0d95-566f-8c45-6b945ae7379e', v_aid, 7, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Чудово! Дорогою можу заскочити в пекарню.", "Добрий день, прошу. Пристебніться, будь ласка.", "Перепрошую, моєї валізи немає на багажній стрічці."]'::jsonb, 2, null, '{}'::text[], 'Oprostite, moj kofer nije na traci za prtljagu.', null, null, 'Прозвучало: «Oprostite, moj kofer nije na traci za prtljagu.» — «Перепрошую, моєї валізи немає на багажній стрічці.».', (select id from public.lessons where id = '69ec0776-4f69-5f86-afac-6652234a7da5'), 'PUBLISHED', 'claude_assessment_v5'),
  ('ec12b77d-0aa4-5f59-af18-af2e36e6fc19', v_aid, 8, 'A1', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Як романтично! Скільки ви разом?", "Даріє, ти коли-небудь була на Хварі?", "Рекс. А тебе як звати, юначе?"]'::jsonb, 1, null, '{}'::text[], 'Darja, jesi li ikad bila na Hvaru?', null, null, 'Прозвучало: «Darja, jesi li ikad bila na Hvaru?» — «Даріє, ти коли-небудь була на Хварі?».', (select id from public.lessons where id = '3f440ad8-f057-5898-b773-6aa8816fa8a3'), 'PUBLISHED', 'claude_assessment_v5'),
  ('d4f7c47d-d377-5adf-97ba-543faace56ab', v_aid, 9, 'A1', 'reading', 'understand', 'multiple_choice', 'Куди викидати пляшку зі скла?', 'Odvajanje otpada', '["У жовтий", "У синій", "У зелений контейнер"]'::jsonb, 2, null, '{}'::text[], null, 'ODVAJAJTE OTPAD!
Plava kanta: papir i karton.
Žuta kanta: plastika i limenke.
Zelena kanta: staklo.
Smeđa kanta: ostaci hrane.
Crna kanta: drugo smeće.
Smeće iznosimo navečer, prije osam sati. Velike stvari ne ostavljajte pored kanti. Hvala što čuvate naš grad!', 'СОРТУЙТЕ ВІДХОДИ!
Синій контейнер: папір і картон.
Жовтий контейнер: пластик і бляшанки.
Зелений контейнер: скло.
Коричневий контейнер: залишки їжі.
Чорний контейнер: інше сміття.
Сміття виносимо ввечері, до восьмої години. Великих речей не залишайте біля контейнерів. Дякуємо, що бережете наше місто!', 'Текст «Сміття й переробка». Правильна відповідь: «У зелений контейнер».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('bc8c9d32-1524-5754-b0d2-05ef0ac669de', v_aid, 10, 'A1', 'reading', 'understand', 'multiple_choice', 'Коли можна забрати картку?', 'E-mail iz banke', '["З понеділка", "Сьогодні", "Через місяць"]'::jsonb, 0, null, '{}'::text[], null, 'Poštovana gospođo Kovalenko,
Vaš tekući račun je otvoren. Debitnu karticu možete pokupiti u banci od ponedjeljka. Za internetsko bankarstvo trebate mobilni token. Provizija za račun je 2 eura mjesečno.
Lijep pozdrav,
Vaša banka', 'Шановна пані Коваленко,
ваш поточний рахунок відкрито. Дебетову картку можна забрати в банку з понеділка. Для інтернет-банкінгу вам потрібен мобільний токен. Комісія за рахунок — 2 євро на місяць.
З повагою,
ваш банк', 'Текст «Лист із банку». Правильна відповідь: «З понеділка».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('9a8725d3-c9ad-555a-96a2-0bd4cb69826b', v_aid, 11, 'A1', 'reading', 'understand', 'multiple_choice', 'Що він робить увечері?', 'Tarasov običan dan', '["Тренується", "Працює", "Читає або дивиться фільм"]'::jsonb, 2, null, '{}'::text[], null, 'Taras živi u Zagrebu. Svaki dan se budi u šest i pol. Prvo se tušira, a onda doručkuje s obitelji. Na posao ide tramvajem. Radi u skladištu od osam do četiri. Poslije posla ide u trgovinu ili u park sa psom. Navečer obično čita ili gleda film. Spava u jedanaest, jer je ujutro opet rano.', 'Тарас живе в Загребі. Щодня він прокидається о пів на сьому. Спочатку приймає душ, а потім снідає з родиною. На роботу їде трамваєм. Працює на складі з восьмої до четвертої. Після роботи йде в магазин або в парк із собакою. Увечері зазвичай читає або дивиться фільм. Лягає спати об одинадцятій, бо вранці знову рано.', 'Текст «Звичайний день Тараса». Правильна відповідь: «Читає або дивиться фільм».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('f2ecaa86-ae23-5bcd-8b22-52749207165c', v_aid, 12, 'A1', 'reading', 'understand', 'multiple_choice', 'Де вечірка?', 'Pozivnica za rođendan', '["У парку", "У ресторані", "У квартирі Івани"]'::jsonb, 2, null, '{}'::text[], null, 'Dragi prijatelji!
U subotu slavim trideseti rođendan i želim vas vidjeti. Zabava je u našem stanu od osam navečer. Imamo hranu i piće, vi donesite dobro raspoloženje! Ako dolazite, javite mi do četvrtka.
Vidimo se,
Ivana', 'Дорогі друзі!
У суботу я святкую тридцятий день народження і хочу вас побачити. Вечірка в нашій квартирі з восьмої вечора. У нас є їжа й напої, а ви принесіть гарний настрій! Якщо прийдете, дайте мені знати до четверга.
До зустрічі,
Івана', 'Текст «Запрошення на день народження». Правильна відповідь: «У квартирі Івани».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('d5051d52-ad53-5c3c-8d52-b004c8f05f47', v_aid, 13, 'A1', 'reading', 'understand', 'multiple_choice', 'Скільки коштує кілограм яблук?', 'Akcija u supermarketu', '["1,49 €", "0,99 €", "3,99 €"]'::jsonb, 0, null, '{}'::text[], null, 'AKCIJA OD PONEDJELJKA DO SUBOTE!
Mlijeko 1 l – 0,99 €
Jabuke 1 kg – 1,49 €
Sir 500 g – 3,99 €
Deterdžent za rublje – minus 30 %
Za kupnju veću od 50 € dobivate vrećicu besplatno.
Plaćanje karticom ili gotovinom.', 'АКЦІЯ З ПОНЕДІЛКА ДО СУБОТИ!
Молоко 1 л – 0,99 €
Яблука 1 кг – 1,49 €
Сир 500 г – 3,99 €
Пральний засіб – мінус 30 %
За покупку понад 50 € отримуєте пакет безкоштовно.
Оплата карткою або готівкою.', 'Текст «Знижки в супермаркеті». Правильна відповідь: «1,49 €».', null, 'PUBLISHED', 'claude_assessment_v5'),
  ('576b1c23-b0cb-5ba6-8187-e7c47f6c8b4d', v_aid, 14, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Mogu. Koliko često ga trebam izvesti?', '["Plaća, ali možete kupiti poseban paket podataka.", "Šetaj psa dvaput dnevno, ujutro i navečer.", "Organizacija. Volim odgovornost."]'::jsonb, 1, null, '{}'::text[], 'Mogu. Koliko često ga trebam izvesti?', null, null, 'Діалог «Поки нас немає»: «Mogu. Koliko često ga trebam izvesti?» (Можу. Як часто його треба виводити?) — «Šetaj psa dvaput dnevno, ujutro i navečer.» (Вигулюй пса двічі на день, уранці й увечері.).', (select id from public.lessons where id = '1968c7d5-4e3a-5b1e-92f6-88df711e9c54'), 'PUBLISHED', 'claude_assessment_v5'),
  ('1f00c82d-e004-5e70-a08b-f04489b75215', v_aid, 15, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Oprostite, imate li šampon za suhu kosu?', '["Imamo. Ovaj je bez parfema, a ima i regenerator.", "Više hodam, manje sjedim i rano idem spavati.", "U trećem b. Tvoja razrednica je učiteljica Ana."]'::jsonb, 0, null, '{}'::text[], 'Oprostite, imate li šampon za suhu kosu?', null, null, 'Діалог «Для волосся й шкіри»: «Oprostite, imate li šampon za suhu kosu?» (Перепрошую, у вас є шампунь для сухого волосся?) — «Imamo. Ovaj je bez parfema, a ima i regenerator.» (Є. Цей без запаху, і до нього є бальзам.).', (select id from public.lessons where id = '9ba8e62a-83fd-5b08-9e01-760bc0f7219f'), 'PUBLISHED', 'claude_assessment_v5'),
  ('25b20448-4d6e-521d-af36-b6b836d88dae', v_aid, 16, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Kako si se sprijateljila s ljudima ovdje?', '["Nećete ništa osjetiti, dobit ćete anesteziju.", "Ultrazvuk srca i kontrolu za tri mjeseca.", "Volontirala sam u udruzi, a ondje je divna zajednica."]'::jsonb, 2, null, '{}'::text[], 'Kako si se sprijateljila s ljudima ovdje?', null, null, 'Діалог «Спогади»: «Kako si se sprijateljila s ljudima ovdje?» (Як ти тут подружилася з людьми?) — «Volontirala sam u udruzi, a ondje je divna zajednica.» (Я волонтерила в організації, а там чудова спільнота.).', (select id from public.lessons where id = '4b2bf351-c5fc-57ca-9fd9-24fb8a4bfc0d'), 'PUBLISHED', 'claude_assessment_v5'),
  ('873cb5f2-1078-56cb-8cce-4bb81dee3130', v_aid, 17, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Bezolovni. Možete li provjeriti i tlak u gumama?', '["Mogu. Prednja lijeva guma je malo mekana.", "Dolje lijevo, kad pijem hladno.", "Stvarno? Mislila sam da je iz Francuske."]'::jsonb, 0, null, '{}'::text[], 'Bezolovni. Možete li provjeriti i tlak u gumama?', null, null, 'Діалог «На заправці»: «Bezolovni. Možete li provjeriti i tlak u gumama?» (Бензин. Можете перевірити ще й тиск у шинах?) — «Mogu. Prednja lijeva guma je malo mekana.» (Можу. Передня ліва шина трохи спущена.).', (select id from public.lessons where id = 'd6ca64d8-4c71-5936-a930-51e400f5681d'), 'PUBLISHED', 'claude_assessment_v5'),
  ('3e3b3503-1866-5d3b-b5e2-5c5040653c26', v_aid, 18, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Gdje ste bili jučer navečer?', '["Šetali smo šetnicom do rimskog foruma.", "U ladici. Stavi i salvete pored tanjura.", "Pouzdana sam i samostalna, a kolege kažu da sam strpljiva."]'::jsonb, 0, null, '{}'::text[], 'Gdje ste bili jučer navečer?', null, null, 'Діалог «Далматинський вечір»: «Gdje ste bili jučer navečer?» (Де ви були вчора ввечері?) — «Šetali smo šetnicom do rimskog foruma.» (Ми гуляли набережною до римського форуму.).', (select id from public.lessons where id = '9a44edc5-7e46-5377-bfcb-20cd93ac333b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('9a9af6b9-0556-50d1-9382-8ab82d2b2a2a', v_aid, 19, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Je li dopušteno ostaviti stari namještaj pored kontejnera?', '["Nije, to je zabranjeno. Zovite odvoz glomaznog otpada.", "Dva dana tjedno. Šef kaže da je to u redu.", "Smiješ, a poslije ćemo probati ronjenje uz obalu."]'::jsonb, 0, null, '{}'::text[], 'Je li dopušteno ostaviti stari namještaj pored kontejnera?', null, null, 'Діалог «Сміття й переробка»: «Je li dopušteno ostaviti stari namještaj pored kontejnera?» (Можна залишити старі меблі біля контейнера?) — «Nije, to je zabranjeno. Zovite odvoz glomaznog otpada.» (Ні, це заборонено. Викличте вивіз великогабаритного сміття.).', (select id from public.lessons where id = 'f296bc84-8059-5981-a5b9-9d4531627e18'), 'PUBLISHED', 'claude_assessment_v5'),
  ('d77d2fde-59e6-5fe4-ad8d-1d0864d22799', v_aid, 20, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Imaš li puno obaveza?', '["Jesmo, a poslije je Pozdrav Suncu svijetlio u svim bojama.", "O hrabrim junacima, vilama i divovima iz starih slavenskih legendi.", "Imam. Petkom pišem izvještaj za nadređenu."]'::jsonb, 2, null, '{}'::text[], 'Imaš li puno obaveza?', null, null, 'Діалог «Як минає день?»: «Imaš li puno obaveza?» (У тебе багато обов’язків?) — «Imam. Petkom pišem izvještaj za nadređenu.» (Багато. По п’ятницях пишу звіт для керівниці.).', (select id from public.lessons where id = 'd813e9c0-2331-59d8-90f1-cea7e9a61c7d'), 'PUBLISHED', 'claude_assessment_v5'),
  ('6b15e375-86c3-51a4-948f-b3306981e1e5', v_aid, 21, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Sedam noćenja. Nudite li polupansion?', '["Nudimo, doručak i večera su uključeni.", "Za vrijeme probnog rada samo tjedan dana.", "Obično sutra. Šaljemo ga na vašu adresu."]'::jsonb, 0, null, '{}'::text[], 'Sedam noćenja. Nudite li polupansion?', null, null, 'Діалог «Бронюємо готель»: «Sedam noćenja. Nudite li polupansion?» (Сім ночей. Ви пропонуєте напівпансіон?) — «Nudimo, doručak i večera su uključeni.» (Так, сніданок і вечеря включені.).', (select id from public.lessons where id = '373074e1-3c4b-5d0f-a4f3-3ed06e0904f2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('876f9681-6940-5cb9-ad13-a86af643098a', v_aid, 22, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Može! Idem s kolegama s posla. Imaš li kostim?', '["Ljeti je puno gostiju, ali kolege su super.", "Imam. Maskirat ću se u gusaricu s crnim šeširom.", "Četrdeset pet minuta, a veliki odmor dvadeset minuta."]'::jsonb, 1, null, '{}'::text[], 'Može! Idem s kolegama s posla. Imaš li kostim?', null, null, 'Діалог «Підемо на карнавал?»: «Može! Idem s kolegama s posla. Imaš li kostim?» (Можна! Я йду з колегами з роботи. У тебе є костюм?) — «Imam. Maskirat ću se u gusaricu s crnim šeširom.» (Є. Я перевдягнуся на піратку в чорному капелюсі.).', (select id from public.lessons where id = 'b026f1b1-879d-59b5-8506-ee99e128c9c1'), 'PUBLISHED', 'claude_assessment_v5'),
  ('62ffb791-da47-5665-bd09-07b02b7fed86', v_aid, 23, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Trebam li antibiotik?', '["Radim na recepciji, a moja prijateljica je sobarica.", "Da, propisat ću vam antibiotik za sedam dana.", "Samo vani. U zgradi vrijedi zabrana pušenja."]'::jsonb, 1, null, '{}'::text[], 'Trebam li antibiotik?', null, null, 'Діалог «Що зі мною?»: «Trebam li antibiotik?» (Мені потрібен антибіотик?) — «Da, propisat ću vam antibiotik za sedam dana.» (Так, я випишу вам антибіотик на сім днів.).', (select id from public.lessons where id = '431b51ad-baa3-5387-94ac-a7273fdb9263'), 'PUBLISHED', 'claude_assessment_v5'),
  ('8aef35a5-277d-5862-a882-f89cb0d3d77c', v_aid, 24, 'A1', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Možete li ga odblokirati?', '["Mogu. Odgovorite na sigurnosno pitanje.", "Zdravstvenu iskaznicu i popis lijekova.", "Preko videopoziva i maila."]'::jsonb, 0, null, '{}'::text[], 'Možete li ga odblokirati?', null, null, 'Діалог «Заблокований акаунт»: «Možete li ga odblokirati?» (Можете його розблокувати?) — «Mogu. Odgovorite na sigurnosno pitanje.» (Можу. Дайте відповідь на контрольне питання.).', (select id from public.lessons where id = 'f355be7d-c423-5651-938e-71b8ca970a62'), 'PUBLISHED', 'claude_assessment_v5'),
  ('7ceaf376-1507-5c85-a3ee-044b87678281', v_aid, 25, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Prvi put si bio u teretani?', '["Моя мама каже, що спорт корисний і для мозку.", "Бережи спину. І дихай глибоко, це добре для легенів і серця.", "Так. І хребет болить."]'::jsonb, 2, null, '{}'::text[], null, 'Marko: Darja, sve me boli, i mišići i zglobovi!
Darja: Prvi put si bio u teretani?
Marko: Jesam. I kralježnica me boli.
Darja: Pazi na leđa. A diši duboko, to je dobro za pluća i srce.
Marko: Moja mama kaže da je sport dobar i za mozak.
Darja: Istina, i za kožu, i za živce!', 'Marko: Даріє, у мене все болить — і м’язи, і суглоби!
Darja: Ти вперше був у спортзалі?
Marko: Так. І хребет болить.
Darja: Бережи спину. І дихай глибоко, це добре для легенів і серця.
Marko: Моя мама каже, що спорт корисний і для мозку.
Darja: Правда, і для шкіри, і для нервів!', 'Діалог «М’язи й суглоби»: «Prvi put si bio u teretani?» — «Jesam. I kralježnica me boli.», тобто «Так. І хребет болить.».', (select id from public.lessons where id = 'b6859b5e-db71-543a-8d05-db9b43811d8a'), 'PUBLISHED', 'claude_assessment_v5'),
  ('dc569191-7951-50f5-9023-3857ed5eb96b', v_aid, 26, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Koliko se dugo čeka odgovor?', '["Засвідчити можна в нотаріуса, це поруч.", "Від мене просять доповнення — засвідчений переклад свідоцтва про народження.", "Зазвичай місяць. Коли схвалять, отримаєш нову картку."]'::jsonb, 2, null, '{}'::text[], null, 'Darja: Traže od mene dopunu, ovjereni prijevod rodnog lista.
Marko: Treba ti sudski tumač za ukrajinski.
Darja: A preslika putovnice? Mora li biti ovjerena?
Marko: Ovjeru možeš napraviti kod javnog bilježnika, blizu je.
Darja: Koliko se dugo čeka odgovor?
Marko: Obično mjesec dana. Kad ti odobre, dobiješ novu iskaznicu.', 'Darja: Від мене просять доповнення — засвідчений переклад свідоцтва про народження.
Marko: Тобі потрібен присяжний перекладач з української.
Darja: А копія паспорта? Вона має бути засвідчена?
Marko: Засвідчити можна в нотаріуса, це поруч.
Darja: Скільки чекати на відповідь?
Marko: Зазвичай місяць. Коли схвалять, отримаєш нову картку.', 'Діалог «Переклад документів»: «Koliko se dugo čeka odgovor?» — «Obično mjesec dana. Kad ti odobre, dobiješ novu iskaznicu.», тобто «Зазвичай місяць. Коли схвалять, отримаєш нову картку.».', (select id from public.lessons where id = 'fe2839bc-fd72-5e8b-bc0e-937d48a90aa8'), 'PUBLISHED', 'claude_assessment_v5'),
  ('5ccf0be3-3ae8-5e6e-9cdf-4a44813176e6', v_aid, 27, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Gdje ćete dočekati Novu godinu?', '["Більшість ні. Ні на День усіх святих, ні на Святого Стефана.", "Перше травня — теж неробочий день, багато хто їде на прогулянку.", "На площі, буде концерт і феєрверк опівночі."]'::jsonb, 2, null, '{}'::text[], null, 'Darja: Gdje ćete dočekati Novu godinu?
Ivana: Na trgu, bit će koncert i vatromet u ponoć.
Darja: Rade li trgovine prvog siječnja?
Ivana: Većina ne radi. Ni za Sve svete ni za Svetog Stjepana.
Darja: A Praznik rada?
Ivana: Prvi svibnja je također neradni dan, mnogi idu na izlet.', 'Darja: Де ви зустрічатимете Новий рік?
Ivana: На площі, буде концерт і феєрверк опівночі.
Darja: Магазини працюють першого січня?
Ivana: Більшість ні. Ні на День усіх святих, ні на Святого Стефана.
Darja: А День праці?
Ivana: Перше травня — теж неробочий день, багато хто їде на прогулянку.', 'Діалог «Новорічна ніч»: «Gdje ćete dočekati Novu godinu?» — «Na trgu, bit će koncert i vatromet u ponoć.», тобто «На площі, буде концерт і феєрверк опівночі.».', (select id from public.lessons where id = '33c041a0-e71a-55c1-94c8-64941876c6d2'), 'PUBLISHED', 'claude_assessment_v5'),
  ('24341042-7319-5f0d-a14e-6b1d1cceeee9', v_aid, 28, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Čestitam! Kako je to bilo?', '["Я досі пам’ятаю, як ти була закохана!", "Три роки. А наше перше побачення було в кіно.", "Мій хлопець запитав мене на пляжі, на заході сонця."]'::jsonb, 2, null, '{}'::text[], null, 'Ivana: Dašo, imam veliku vijest. Zaručila sam se!
Daša: Čestitam! Kako je to bilo?
Ivana: Moj dečko me pitao na plaži, za zalazak sunca.
Daša: Kako romantično! Koliko ste dugo u vezi?
Ivana: Tri godine. A prvi spoj nam je bio u kinu.
Daša: Još se sjećam koliko si bila zaljubljena!', 'Ivana: Дашо, у мене велика новина. Я заручилася!
Daša: Вітаю! Як це було?
Ivana: Мій хлопець запитав мене на пляжі, на заході сонця.
Daša: Як романтично! Скільки ви разом?
Ivana: Три роки. А наше перше побачення було в кіно.
Daša: Я досі пам’ятаю, як ти була закохана!', 'Діалог «Новини від подруги»: «Čestitam! Kako je to bilo?» — «Moj dečko me pitao na plaži, za zalazak sunca.», тобто «Мій хлопець запитав мене на пляжі, на заході сонця.».', (select id from public.lessons where id = '0d0547ed-c0ef-53bd-bfe4-c482c84c40f4'), 'PUBLISHED', 'claude_assessment_v5'),
  ('8305de12-6c58-5f67-9797-7a8bad14b2d5', v_aid, 29, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Imate li bežične slušalice s mikrofonom?', '["Є, ці дешевші за ті.", "До годинника ви отримаєте в подарунок чохол і захисне скло.", "Мій син хоче ще й смарт-годинник."]'::jsonb, 0, null, '{}'::text[], null, 'Marko: Imate li bežične slušalice s mikrofonom?
Prodavačica: Imamo, ove su jeftinije od onih.
Marko: Moj sin želi i pametni sat.
Prodavačica: Uz sat dobijete futrolu i zaštitno staklo na poklon.
Marko: Super. A mali zvučnik za tablet?
Prodavačica: Na polici pored USB ključića.', 'Marko: У вас є бездротові навушники з мікрофоном?
Prodavačica: Є, ці дешевші за ті.
Marko: Мій син хоче ще й смарт-годинник.
Prodavačica: До годинника ви отримаєте в подарунок чохол і захисне скло.
Marko: Чудово. А маленький динамік для планшета?
Prodavačica: На полиці біля флешок.', 'Діалог «Подарунок синові»: «Imate li bežične slušalice s mikrofonom?» — «Imamo, ove su jeftinije od onih.», тобто «Є, ці дешевші за ті.».', (select id from public.lessons where id = '31bbedca-4b51-5478-8513-df5cb996ffd9'), 'PUBLISHED', 'claude_assessment_v5'),
  ('9f4686ba-1d4b-547d-a698-25d8a482f58a', v_aid, 30, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Oprostite, ima li u ovom kolaču oraha?', '["Є волоські горіхи й трохи арахісу.", "У нас є й паста без глютену, тільки скажіть.", "Тоді не можу, у мене алергія на арахіс."]'::jsonb, 0, null, '{}'::text[], null, 'Daša: Oprostite, ima li u ovom kolaču oraha?
Ivan: Ima oraha i malo kikirikija.
Daša: Onda ne mogu, alergična sam na kikiriki.
Ivan: Imamo voćnu salatu, ona je bez oraha.
Daša: Super. A je li tjestenina bez glutena?
Ivan: Imamo i tjesteninu bez glutena, samo recite.', 'Daša: Перепрошую, у цьому тістечку є горіхи?
Ivan: Є волоські горіхи й трохи арахісу.
Daša: Тоді не можу, у мене алергія на арахіс.
Ivan: У нас є фруктовий салат, він без горіхів.
Daša: Чудово. А паста без глютену?
Ivan: У нас є й паста без глютену, тільки скажіть.', 'Діалог «У ресторані з алергією»: «Oprostite, ima li u ovom kolaču oraha?» — «Ima oraha i malo kikirikija.», тобто «Є волоські горіхи й трохи арахісу.».', (select id from public.lessons where id = '6af82dd3-beb1-54cf-9c1b-44ec3cb12a35'), 'PUBLISHED', 'claude_assessment_v5'),
  ('03a7a6f0-be94-5a18-b9fc-646b2bbba69e', v_aid, 31, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Крок за кроком». Що ви скажете?', null, '["Trebam prvi slobodni termin.", "Korak po korak.", "Gdje je najbliže odmorište?"]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Крок за кроком.» — «Korak po korak.».', (select id from public.lessons where id = '4b2bf351-c5fc-57ca-9fd9-24fb8a4bfc0d'), 'PUBLISHED', 'claude_assessment_v5'),
  ('167342b6-6fba-52cb-92df-af8433e3864d', v_aid, 32, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я їду в Задар». Що ви скажете?', null, '["Putujem u Zadar.", "Gdje je automat za parkiranje?", "Ustupite mjesto baki."]'::jsonb, 0, null, '{}'::text[], null, null, null, '«Я їду в Задар.» — «Putujem u Zadar.».', (select id from public.lessons where id = 'c1b32b15-8f3c-5f75-bba9-e831d544ec7b'), 'PUBLISHED', 'claude_assessment_v5'),
  ('8af2ec9e-4772-59fe-9af0-5a3ee3432beb', v_aid, 33, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я застуджений, сьогодні не прийду». Що ви скажете?', null, '["Radim u tvornici.", "Prehlađen sam, danas ne dolazim.", "Skenirajte ugovor, molim."]'::jsonb, 1, null, '{}'::text[], null, null, null, '«Я застуджений, сьогодні не прийду.» — «Prehlađen sam, danas ne dolazim.».', (select id from public.lessons where id = 'e806dd39-4d38-5781-ad2d-949961dd95f9'), 'PUBLISHED', 'claude_assessment_v5'),
  ('497a4b22-f395-59e7-bbf7-a337b9150964', v_aid, 34, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я хочу дві яєчні-глазуньї». Що ви скажете?', null, '["Želim dva jaja na oko.", "Postavi stol, molim te.", "Imate li plodove mora?"]'::jsonb, 0, null, '{}'::text[], null, null, null, '«Я хочу дві яєчні-глазуньї.» — «Želim dva jaja na oko.».', (select id from public.lessons where id = 'bb7bc159-cb40-5a8a-91b7-c6da05c6342a'), 'PUBLISHED', 'claude_assessment_v5'),
  ('c4b5128b-ee41-5db4-a3f9-68c44bcd3bf2', v_aid, 35, 'A1', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Можете розблокувати акаунт?». Що ви скажете?', null, '["Podijelila sam objavu u grupi.", "Kako se ovo uključuje?", "Možete li odblokirati račun?"]'::jsonb, 2, null, '{}'::text[], null, null, null, '«Можете розблокувати акаунт?» — «Možete li odblokirati račun?».', (select id from public.lessons where id = 'f355be7d-c423-5651-938e-71b8ca970a62'), 'PUBLISHED', 'claude_assessment_v5'),
